// Mutates only the synthetic fixture generated by package-integration.mjs.
import assert from 'node:assert/strict';
import { readFile, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { inside } from '../../lib/paths.mjs';
import { unzipSync } from 'fflate';

const project = fileURLToPath(new URL('../../../', import.meta.url));
const metadata = JSON.parse(await readFile(join(project, '.astro/tool-packages-phase-b/manifest.json')));
assert(inside(resolve(project, '.astro/tool-packages-phase-b'), resolve(metadata.run)));
const base = `http://127.0.0.1:${metadata.devPort}/blog/`;
const app = join(metadata.notes, 'day/timestamp/app.js');
const manifest = join(metadata.notes, 'day/timestamp/manifest.json');
const note = join(metadata.notes, 'day/note.md');
const previous = await Promise.all([readFile(app), readFile(manifest), readFile(note)]);
const report = { results: [], restored: false, cloudWrites: false };
const get = path => fetch(base + path, { signal: AbortSignal.timeout(2500) });
const wait = async (name, check) => {
  const deadline = Date.now() + 25000;
  while (Date.now() < deadline) {
    try { if (await check()) { report.results.push(name); console.log('PASS ' + name); return; } } catch {}
    await new Promise(done => setTimeout(done, 150));
  }
  throw new Error('Dev update timed out: ' + name);
};
const first = 'posts/first/timestamp/';
const second = 'posts/second/_attachments/day/timestamp/';
const zip = async prefix => {
  const response = await get(prefix.slice(0, -1) + '.zip');
  assert.equal(response.status, 200);
  return unzipSync(new Uint8Array(await response.arrayBuffer()));
};
try {
  await writeFile(app, previous[0].toString().replace('timestamp-2', 'timestamp-3'));
  await wait('JS-only edit serves updated bytes for both article copies', async () =>
    (await (await get(first + 'app.js')).text()).includes('timestamp-3') && (await (await get(second + 'app.js')).text()).includes('timestamp-3'));
  await wait('JS-only edit refreshes both ZIP member bytes', async () =>
    Buffer.from((await zip(first))['app.js']).toString().includes('timestamp-3') && Buffer.from((await zip(second))['app.js']).toString().includes('timestamp-3'));
  const data = JSON.parse(previous[1]);
  data.files = data.files.filter(file => file !== 'app.js');
  await writeFile(manifest, JSON.stringify(data));
  await wait('manifest-only removal stops serving both old dependency paths', async () =>
    (await get(first + 'app.js')).status === 404 && (await get(second + 'app.js')).status === 404);
  await wait('manifest-only removal excludes dependency from both ZIPs', async () =>
    !Object.hasOwn(await zip(first), 'app.js') && !Object.hasOwn(await zip(second), 'app.js'));
  await writeFile(manifest, previous[1]);
  await wait('manifest restoration re-registers both dependencies', async () =>
    (await get(first + 'app.js')).status === 200 && (await get(second + 'app.js')).status === 200);
  await writeFile(manifest, JSON.stringify({ ...JSON.parse(previous[1]), download: false }));
  await wait('turning download off removes both archives and article controls while online entry stays available', async () =>
    (await get(first.slice(0, -1) + '.zip')).status === 404 && (await get(second.slice(0, -1) + '.zip')).status === 404
    && !(await (await get('posts/first/')).text()).includes('download="timestamp.zip"') && (await get(first + 'index.html')).status === 200);
  await writeFile(manifest, previous[1]);
  await wait('turning download on restores archive generation', async () => (await get(first.slice(0, -1) + '.zip')).status === 200);
  await writeFile(note, '---\npublish: false\n---\nWithdrawn fixture');
  await wait('withdrawal removes article, entry and directory alias; shared copy remains', async () =>
    (await get('posts/first/')).status === 404 && (await get(first)).status === 404
    && (await get(first + 'index.html')).status === 404 && (await get(first.slice(0, -1) + '.zip')).status === 404
    && (await get(second)).status === 200 && (await get(second.slice(0, -1) + '.zip')).status === 200);
} finally {
  for (const [index, path] of [app, manifest, note].entries()) await writeFile(path, previous[index]);
  await wait('synthetic fixture restored for review', async () => (await get(first)).status === 200 && (await (await get(first + 'app.js')).text()).includes('timestamp-2'));
  report.restored = true;
  await writeFile(join(metadata.run, 'dev-updates-report.json'), JSON.stringify(report, null, 2) + '\n');
}
